import Base
type BindingQuote is Data:
  BindingClosed{}
  BindingNewline{}
type BindingState is Data:
  BindingQuoted{quote: Nat, beg: Nat, rev: Nat, escaped: Bool, kind: BindingQuote}
def binding_identity(x: Nat, state: BindingState) -> Nat:
  match x state:
    case +c BindingQuoted{+quote, +beg, +rev, True{}, _}: beg
    case +c BindingQuoted{+quote, +beg, +rev, False{}, BindingClosed{}}: beg
    case +c BindingQuoted{+quote, +beg, +rev, False{}, BindingNewline{}}: beg
